def hidden_rule_fn(state):
    # Rule: append (last * second_last) % 11 to the state
    if len(state) >= 2:
        new_element = (state[-1] * state[-2]) % 11
        return state + [new_element]
    else:
        # If fewer than 2 elements, return state as-is
        return state
